ok=True
for i in range(15):
    for j in range(13):
        l=inp[i][j]; r=inp[i][j+14]
        pred=(l+1) if l==r else min(l,r)
        if pred!=out[i][j]:
            ok=False; print(i,j,l,r,pred,out[i][j])
print("min/eq+1 rule ok:",ok)
# alternative: max? xor-of-colors? check others quickly
def check(f):
    return all(f(inp[i][j],inp[i][j+14])==out[i][j] for i in range(15) for j in range(13))
print("max/eq+1:",check(lambda l,r:(l+1) if l==r else max(l,r)))
print("sum mod:",check(lambda l,r:(l+r)%10))
